@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800;900&display=swap');
:root{--ink:#f7f2ff;--muted:#a19bb6;--purple:#a889ff;--pink:#ff8bbc;--bg:#100d24;--line:rgba(255,255,255,.12);font-family:'Outfit',sans-serif;color:var(--ink);background:var(--bg);font-synthesis:none}
*{box-sizing:border-box}body{margin:0;min-width:320px;min-height:100vh;background:radial-gradient(ellipse at 50% 12%,#211744 0,#100d24 55%,#0b0918 100%);overflow-x:hidden}.app-shell{width:min(1220px,calc(100% - 64px));margin:auto}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08)}.wordmark{text-decoration:none;color:#fff;font-size:17px;font-weight:800;letter-spacing:.07em;display:flex;align-items:center;gap:8px}.brand-mark{color:#ff9ac6;font-size:25px;line-height:1}.wordmark-light{font-size:11px;font-weight:500;letter-spacing:.17em;color:#a49bb7;margin-left:4px}.top-meta,.sound-toggle,.eyebrow,.start-note,.controls-hint,.stage-footer,.how-title,.how-keys,.page-footer{font-family:'DM Mono',monospace}.top-meta{color:#9e97b3;font-size:10px;letter-spacing:.12em;display:flex;align-items:center;gap:10px}.live-dot,.footer-dot{width:7px;height:7px;border-radius:50%;background:#a6f1c4;box-shadow:0 0 12px #a6f1c4}.meta-divider{color:#514968}.sound-toggle{border:1px solid var(--line);border-radius:100px;background:#ffffff06;color:#d9d3e8;padding:10px 14px;font-size:9px;letter-spacing:.09em;display:flex;align-items:center;gap:8px;cursor:pointer}.sound-icon{font-size:14px;color:#ff9ac6}.game-wrap{margin-top:30px}.stage-frame{height:min(64vw,610px);min-height:460px;position:relative;overflow:hidden;border:1px solid rgba(216,194,255,.2);border-radius:9px;background:#15102c;box-shadow:0 22px 90px #070512a6,inset 0 0 0 5px #090716;isolation:isolate}canvas{width:100%;height:100%;display:block}.stage-grain,.stage-vignette{position:absolute;inset:0;pointer-events:none}.stage-grain{opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.3'/%3E%3C/svg%3E");mix-blend-mode:screen}.stage-vignette{background:linear-gradient(90deg,rgba(10,8,24,.38),transparent 30%,transparent 70%,rgba(10,8,24,.4)),linear-gradient(0deg,rgba(10,8,24,.5),transparent 35%)}.overlay{position:absolute;inset:0;z-index:3;display:flex;align-items:center;justify-content:center;text-align:center;background:linear-gradient(90deg,rgba(16,12,35,.18),rgba(16,12,35,.44) 43%,rgba(16,12,35,.13));}.overlay[hidden],.hud[hidden],.mobile-controls[hidden]{display:none!important}.intro-copy{position:relative;z-index:1;transform:translateY(-3px)}.eyebrow{font-size:9px;letter-spacing:.24em;color:#c2b5dc;display:flex;gap:12px;align-items:center;justify-content:center}.eyebrow-line{height:1px;width:28px;background:#8e77b9}h1{font-size:clamp(50px,7vw,85px);line-height:.84;letter-spacing:-.055em;margin:23px 0 17px;font-weight:900}h1 em,.result-card h2 em{font-style:normal;color:#ff9cc9;text-shadow:0 0 30px #ff5daa55}.intro-copy>p{font-size:14px;line-height:1.55;color:#c0bad0;margin:0 auto 22px}.difficulty-row{display:flex;justify-content:center;gap:7px;margin:0 0 15px}.difficulty{font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#a49bb7;background:#ffffff07;border:1px solid #ffffff19;border-radius:3px;padding:8px 13px;cursor:pointer;transition:.2s}.difficulty small{color:#755d9a;margin-left:4px}.difficulty.active{color:#fff;border-color:#c49eff;background:#a889ff22;box-shadow:0 0 18px #9c78ff22}.play-button{border:0;border-radius:3px;background:linear-gradient(100deg,#ff95c2,#bc91ff);color:#1b1234;min-width:220px;padding:0 16px 0 23px;height:49px;display:inline-flex;align-items:center;justify-content:space-between;gap:32px;font:700 11px 'DM Mono',monospace;letter-spacing:.13em;cursor:pointer;box-shadow:0 8px 25px #e68dff38;transition:transform .2s,box-shadow .2s}.play-button:hover{transform:translateY(-2px);box-shadow:0 12px 30px #e68dff55}.play-button b{font:20px 'Outfit',sans-serif}.start-note{font-size:8px;color:#8f88a5;letter-spacing:.13em;margin-top:12px}.hero-sticker{position:absolute;right:9%;top:20%;transform:rotate(11deg);border:1px solid #ff9cc9aa;color:#ffc2dc;padding:11px 12px 10px;font-size:13px;font-weight:900;line-height:.92;text-align:left;letter-spacing:.07em;background:#2519378c;box-shadow:4px 4px 0 #ff9cc933}.hero-sticker span{color:#ff9cc9}.hero-sticker b{position:absolute;font-size:18px;right:-9px;top:-11px;color:#ff9cc9}.controls-hint{position:absolute;bottom:20px;left:0;right:0;display:flex;align-items:center;justify-content:center;gap:7px;font-size:8px;letter-spacing:.1em;color:#aaa2bd}.keycap{border:1px solid #ffffff4c;border-bottom-width:2px;border-radius:4px;background:#ffffff0b;min-width:23px;height:22px;display:inline-flex;align-items:center;justify-content:center;color:#fff;font:10px 'DM Mono',monospace}.hud{position:absolute;z-index:2;left:30px;right:30px;top:24px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.hud-label,.song-name,.combo-value small{font:9px 'DM Mono',monospace;letter-spacing:.16em;color:#b8accb}.score-value{font:24px 'DM Mono',monospace;letter-spacing:.05em;margin-top:5px;text-shadow:0 0 15px #cbacff88}.hud-center{width:42%;text-align:center;padding-top:2px}.song-name{font-size:9px}.song-name span{color:#8f869f}.progress-track{height:2px;background:#ffffff22;margin-top:11px}.progress-track i{height:100%;display:block;width:0;background:linear-gradient(90deg,#ff92c4,#b99aff);box-shadow:0 0 8px #f6aaff;transition:width .1s}.hud-right{text-align:right;min-width:80px}.combo-value{font:24px 'DM Mono',monospace;color:#ff9ac6;text-shadow:0 0 14px #ff75b688}.combo-value small{font-size:8px;display:block;margin-top:-3px}.health-bar{height:4px;width:76px;background:#ffffff2b;margin:10px 0 0 auto}.health-bar i{display:block;width:100%;height:100%;background:#a6f1c4;transition:width .2s}.pause-overlay,.result-overlay{background:#100c24b8;backdrop-filter:blur(8px)}.pause-card,.result-card{width:min(400px,90%);padding:36px 30px;background:#17112c;border:1px solid #ffffff24;box-shadow:0 15px 70px #08061399}.pause-card h2,.result-card h2{font-size:48px;line-height:.9;letter-spacing:-.05em;margin:20px 0 10px;font-weight:900}.pause-card h2 span{color:#ff9cc9}.pause-card p{color:#b4acc5;font-size:13px;margin:0 0 23px}.pause-card .play-button,.result-card .play-button{width:100%;margin-top:8px}.text-button{display:block;margin:14px auto 0;border:0;background:none;color:#aaa0ba;font:9px 'DM Mono',monospace;letter-spacing:.13em;cursor:pointer;padding:7px}.text-button:hover{color:#fff}.result-card{width:min(440px,92%);padding:28px 34px}.result-card h2{font-size:43px;margin:15px 0 18px}.result-score{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #ffffff1b;border-bottom:1px solid #ffffff1b;padding:12px 0;font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#b7aec8}.result-score b{font-size:20px;color:#fff}.result-stats{display:flex;justify-content:space-between;padding:15px 4px}.result-stats div{display:grid;gap:4px}.result-stats b{font:20px 'DM Mono',monospace;color:#ff9cc9}.result-stats span{font:8px 'DM Mono',monospace;color:#9890a8;letter-spacing:.08em}.feedback{position:absolute;z-index:4;left:50%;top:28%;transform:translate(-50%,-50%);font:800 21px 'Outfit',sans-serif;font-style:italic;letter-spacing:.1em;color:#fff;text-shadow:0 2px 20px #ff7db9;opacity:0;pointer-events:none}.feedback.pop{animation:feedback .55s ease-out}@keyframes feedback{0%{opacity:0;transform:translate(-50%,0) scale(.8)}25%{opacity:1;transform:translate(-50%,-10px) scale(1.05)}100%{opacity:0;transform:translate(-50%,-27px) scale(1)}}.mobile-controls{display:none}.stage-footer{height:42px;display:flex;align-items:center;justify-content:space-between;color:#8e879e;font-size:8px;letter-spacing:.1em}.stage-footer>div{display:flex;align-items:center;gap:8px}.footer-dot{width:5px;height:5px}.footer-star{font-size:15px;color:#ff9ac6}.below-stage{display:flex;align-items:center;gap:35px;border-top:1px solid #ffffff12;border-bottom:1px solid #ffffff12;padding:25px 0;margin-top:14px}.how-title{font-size:10px;letter-spacing:.13em;white-space:nowrap}.how-title span{color:#ff9ac6;margin-right:8px}.below-stage p{font-size:11px;line-height:1.6;color:#aaa3b8;max-width:470px;margin:0}.how-keys{display:grid;grid-template-columns:23px 23px 48px auto auto auto;align-items:center;gap:5px;margin-left:auto}.how-keys small{font-size:7px;color:#8f879f;margin-left:2px}.page-footer{height:56px;display:flex;align-items:center;justify-content:space-between;color:#79728c;font-size:8px;letter-spacing:.1em}
@media(max-width:760px){.app-shell{width:calc(100% - 28px)}.topbar{height:63px}.top-meta{display:none}.game-wrap{margin-top:15px}.stage-frame{height:min(122vw,650px);min-height:500px;max-height:70svh;border-radius:6px}.hero-sticker{right:7%;top:12%;font-size:10px;padding:8px}.intro-copy{transform:translateY(-8px)}h1{font-size:clamp(49px,12vw,76px)}.intro-copy>p{font-size:12px}.controls-hint{bottom:15px}.hud{left:16px;right:16px;top:16px}.hud-center{width:35%}.song-name{font-size:7px}.song-name span{display:none}.score-value,.combo-value{font-size:18px}.mobile-controls{display:flex;position:absolute;z-index:5;bottom:12px;left:12px;right:12px;gap:10px}.mobile-controls button{flex:1;height:52px;border:1px solid #ffffff35;border-radius:5px;background:#21183fa8;color:#fff;font:20px 'Outfit',sans-serif;touch-action:manipulation;backdrop-filter:blur(5px)}.mobile-controls button:active{background:#ff9ac655;border-color:#ff9ac6}.mobile-controls small{font:8px 'DM Mono',monospace;letter-spacing:.1em;margin-left:8px;color:#c1b6d2}.stage-footer{font-size:7px}.footer-center{display:none!important}.below-stage{display:block;padding:18px 0}.below-stage p{margin:12px 0}.how-keys{margin:14px 0 0;grid-template-columns:23px 23px 48px auto auto auto}.page-footer{font-size:7px}.wordmark{font-size:14px}.wordmark-light{font-size:9px}.result-card{padding:25px 22px}}
@media(max-height:700px) and (min-width:761px){.stage-frame{height:500px;min-height:420px}.game-wrap{margin-top:18px}.topbar{height:65px}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {
    intro: $('introOverlay'), pause: $('pauseOverlay'), result: $('resultOverlay'), hud: $('hud'),
    score: $('score'), combo: $('combo'), health: $('health'), progress: $('progress'),
    feedback: $('feedback'), controls: $('mobileControls'), soundLabel: $('soundLabel')
  };
  const settings = { chill: { bpm: 94, beats: 56, window: .22 }, rush: { bpm: 116, beats: 64, window: .18 }, fever: { bpm: 138, beats: 72, window: .15 } };
  let difficulty = 'chill', state = 'menu', soundOn = true, audio = null, startAt = 0, lastFrame = 0;
  let notes = [], particles = [], stars = [], buildings = [], score = 0, combo = 0, bestCombo = 0, health = 100, hits = 0, attempts = 0, elapsed = 0, lastBeat = -1;
  let W = 0, H = 0, dpr = 1, feedbackTimer = 0;
  const rand = (a,b) => a + Math.random() * (b-a);
  const clamp = (n,a,b) => Math.max(a,Math.min(b,n));

  function resize() {
    const r = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = r.width; H = r.height;
    canvas.width = Math.round(W*dpr); canvas.height = Math.round(H*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
    seedScenery();
  }
  function seedScenery() {
    stars = Array.from({length:80}, () => ({x:rand(0,W),y:rand(0,H*.59),r:rand(.4,1.8),p:rand(0,6.28),s:rand(.2,1)}));
    buildings=[]; let x=-5;
    while(x<W+20){const w=rand(22,70),h=rand(H*.08,H*.27);buildings.push({x,w,h,seed:rand(0,10)});x+=w+rand(4,12)}
  }
  window.addEventListener('resize',resize); resize();

  function audioStart() {
    if (!soundOn) return;
    try {
      audio = audio || new (window.AudioContext || window.webkitAudioContext)();
      if (audio.state === 'suspended') audio.resume();
    } catch (_) { audio = null; }
  }
  function tone(freq, when, duration, type='sine', volume=.04, endFreq=null) {
    if (!soundOn || !audio) return;
    const osc=audio.createOscillator(), gain=audio.createGain();
    osc.type=type; osc.frequency.setValueAtTime(freq,when);
    if(endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20,endFreq),when+duration);
    gain.gain.setValueAtTime(.0001,when); gain.gain.exponentialRampToValueAtTime(volume,when+.008); gain.gain.exponentialRampToValueAtTime(.0001,when+duration);
    osc.connect(gain);gain.connect(audio.destination);osc.start(when);osc.stop(when+duration+.02);
  }
  function beatSound(t, beat) {
    if (!audio || !soundOn) return;
    const now=audio.currentTime;
    if(beat%4===0) tone(115,now,.16,'sine',.085,42);
    else if(beat%4===2) tone(180,now,.09,'triangle',.028,90);
    tone(beat%2===0?950:720,now,.035,'square',.009,350);
  }
  function hitSound(lane, quality) {
    tone(lane===0?520:660,audio?audio.currentTime:0,.12,'sine',quality==='PERFECT'?.065:.04,quality==='PERFECT'?880:540);
  }

  function buildNotes() {
    const cfg=settings[difficulty], beat=60/cfg.bpm;
    notes=[];
    for(let i=0;i<cfg.beats;i++){
      // A deliberately composed-feeling pattern with occasional offbeat doubles.
      const lane=(Math.floor(i/4)+i+Math.floor(i/7))%2;
      if(i%8===3 || i%8===6) notes.push({time:(i+.5)*beat,lane:(lane+1)%2,done:false});
      notes.push({time:i*beat,lane,done:false});
      if(difficulty==='fever' && i%4===1) notes.push({time:(i+.5)*beat,lane,done:false});
    }
    notes.sort((a,b)=>a.time-b.time);
  }
  function startGame() {
    audioStart(); buildNotes(); score=0;combo=0;bestCombo=0;health=100;hits=0;attempts=0;elapsed=0;lastBeat=-1;particles=[];
    startAt=performance.now()/1000;state='playing';
    ui.intro.hidden=true;ui.pause.hidden=true;ui.result.hidden=true;ui.hud.hidden=false;ui.controls.hidden=false;
    updateHud();
  }
  function pauseGame(){if(state!=='playing')return;state='paused';ui.pause.hidden=false;ui.controls.hidden=true;}
  function resumeGame(){if(state!=='paused')return;startAt=performance.now()/1000-elapsed;state='playing';ui.pause.hidden=true;ui.controls.hidden=false;}
  function endGame(){
    if(state==='result')return;
    state='result';ui.hud.hidden=true;ui.controls.hidden=true;ui.result.hidden=false;
    $('finalScore').textContent=String(score).padStart(6,'0');$('bestCombo').textContent=bestCombo;
    const accuracy=attempts?Math.round(hits/attempts*100):0;$('accuracy').textContent=accuracy+'%';
    const rank=score>=85000?'S':score>=62000?'A':score>=38000?'B':'C';$('rank').textContent=rank;
    $('resultTitle').innerHTML=rank==='S'?'YOU ARE<br><em>THE MOMENT.</em>':rank==='A'?'THAT WAS<br><em>GLOWING.</em>':'NICE WORK.<br><em>KEEP GOING.</em>';
    $('resultEyebrow').textContent=health<=0?'THE NIGHT GOES ON':'NIGHT COMPLETE';
  }
  function updateHud(){ui.score.textContent=String(score).padStart(6,'0');ui.combo.textContent=combo;ui.health.style.width=health+'%';ui.health.style.background=health<30?'#ff8b9b':'#a6f1c4';}
  function showFeedback(text){ui.feedback.textContent=text;ui.feedback.classList.remove('pop');void ui.feedback.offsetWidth;ui.feedback.classList.add('pop');}
  function addParticles(x,y,color,count=10){for(let i=0;i<count;i++)particles.push({x,y,vx:rand(-120,120),vy:rand(-130,35),life:rand(.28,.65),max:.65,r:rand(1,3),color});}

  function hit(lane) {
    if(state!=='playing') return;
    const cfg=settings[difficulty];
    let candidate=null,delta=Infinity;
    for(const n of notes){if(n.done||n.lane!==lane)continue;const d=Math.abs(n.time-elapsed);if(d<delta){candidate=n;delta=d}}
    attempts++;
    if(candidate && delta<=cfg.window){
      candidate.done=true;hits++;
      const perfect=delta<=cfg.window*.42, quality=perfect?'PERFECT':'NICE';
      combo++;bestCombo=Math.max(combo,bestCombo);score+=(perfect?1000:650)+Math.min(combo,50)*10;
      health=clamp(health+(perfect?1.6:.8),0,100);showFeedback(quality);hitSound(lane,quality);
      addParticles(W*.19,H*(lane===0?.635:.765),lane===0?'#ff9fc9':'#b8a2ff',perfect?14:9);
    } else {combo=0;health=clamp(health-7,0,100);showFeedback('MISS');}
    updateHud();if(health<=0)endGame();
  }
  function press(key){if(key==='f'||key==='arrowleft'||key==='a')hit(0);if(key==='j'||key==='arrowright'||key==='d')hit(1);}
  window.addEventListener('keydown',e=>{
    const k=e.key.toLowerCase();if([' ','arrowleft','arrowright'].includes(k))e.preventDefault();
    if((k===' '||k==='escape')&&state==='playing'){pauseGame();return}if((k===' '||k==='escape')&&state==='paused'){resumeGame();return}
    if(k==='f'||k==='j'||k==='arrowleft'||k==='arrowright'||k==='a'||k==='d')press(k);
  });
  document.querySelectorAll('.mobile-controls button').forEach(b=>{
    const action=e=>{e.preventDefault();hit(Number(b.dataset.lane));};
    b.addEventListener('pointerdown',action);b.addEventListener('click',action);
  });
  // Avoid double firing on browsers that dispatch both pointerdown and click.
  document.querySelectorAll('.mobile-controls button').forEach(b=>b.addEventListener('click',e=>e.stopPropagation()));
  $('playButton').addEventListener('click',startGame);$('againButton').addEventListener('click',startGame);$('resumeButton').addEventListener('click',resumeGame);
  $('quitButton').addEventListener('click',()=>{state='menu';ui.pause.hidden=true;ui.hud.hidden=true;ui.controls.hidden=true;ui.intro.hidden=false});
  $('homeButton').addEventListener('click',()=>{state='menu';ui.result.hidden=true;ui.intro.hidden=false});
  document.querySelectorAll('.difficulty').forEach(b=>b.addEventListener('click',()=>{difficulty=b.dataset.difficulty;document.querySelectorAll('.difficulty').forEach(x=>x.classList.toggle('active',x===b));}));
  $('soundToggle').addEventListener('click',()=>{soundOn=!soundOn;ui.soundLabel.textContent=soundOn?'SOUND ON':'SOUND OFF';if(soundOn)audioStart();});

  function roundedRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
  function drawBackground(t){
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1b1638');g.addColorStop(.52,'#302052');g.addColorStop(1,'#111027');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    const moonX=W*.72,moonY=H*.22,moonR=Math.min(W,H)*.09;
    const glow=ctx.createRadialGradient(moonX,moonY,2,moonX,moonY,moonR*2.9);glow.addColorStop(0,'#f9a9d92a');glow.addColorStop(1,'#e497f000');ctx.fillStyle=glow;ctx.fillRect(moonX-moonR*3,moonY-moonR*3,moonR*6,moonR*6);
    ctx.beginPath();ctx.arc(moonX,moonY,moonR,0,Math.PI*2);ctx.fillStyle='#f9c5de';ctx.globalAlpha=.78;ctx.fill();ctx.globalAlpha=1;
    for(const s of stars){ctx.globalAlpha=.25+.55*(.5+.5*Math.sin(t*s.s+s.p));ctx.fillStyle='#fff4f5';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,6.28);ctx.fill()}ctx.globalAlpha=1;
    // distant hills
    ctx.beginPath();ctx.moveTo(0,H*.56);for(let x=0;x<=W;x+=20)ctx.lineTo(x,H*.48+Math.sin(x*.008+1)*H*.035+Math.sin(x*.019)*H*.014);ctx.lineTo(W,H*.66);ctx.lineTo(0,H*.66);ctx.closePath();ctx.fillStyle='#211a3a';ctx.fill();
    for(const b of buildings){ctx.fillStyle='#15132d';ctx.fillRect(b.x,H*.58-b.h,b.w,b.h);for(let wy=H*.6-b.h;wy<H*.58-5;wy+=12){for(let wx=b.x+6;wx<b.x+b.w-4;wx+=11){if(Math.sin(wx*1.17+wy*2+b.seed)>-.08){ctx.fillStyle=Math.sin(wx+wy)>0?'#ffb1d344':'#a88aff30';ctx.fillRect(wx,wy,3,5)}}}}
    // road glow and lanes
    const horizon=H*.56, floor=H*.92;
    ctx.beginPath();ctx.moveTo(W*.24,horizon);ctx.lineTo(W*.76,horizon);ctx.lineTo(W*1.04,floor);ctx.lineTo(-W*.04,floor);ctx.closePath();const road=ctx.createLinearGradient(0,horizon,0,floor);road.addColorStop(0,'#36234f');road.addColorStop(1,'#17152d');ctx.fillStyle=road;ctx.fill();
    for(let i=0;i<15;i++){const y=horizon+(floor-horizon)*(i/14);const scale=(y-horizon)/(floor-horizon);ctx.strokeStyle=`rgba(222,167,245,${.04+scale*.12})`;ctx.lineWidth=1+scale*1.2;ctx.beginPath();ctx.moveTo(W*.5-(W*.26+scale*W*.24),y);ctx.lineTo(W*.5+(W*.26+scale*W*.24),y);ctx.stroke()}
    ctx.strokeStyle='#ff9fce42';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W*.5,horizon);ctx.lineTo(-W*.04,floor);ctx.moveTo(W*.5,horizon);ctx.lineTo(W*1.04,floor);ctx.stroke();
    // Decorative sky streaks move with the music.
    const pulse=state==='playing'?.5+.5*Math.sin(t*settings[difficulty].bpm*Math.PI/30):.25+.1*Math.sin(t);
    ctx.globalAlpha=.12+pulse*.09;ctx.fillStyle='#ff9ac6';ctx.fillRect(0,H*.55,W,1);ctx.globalAlpha=1;
  }
  function drawLane(lane,t){
    const y=H*(lane===0?.635:.765),col=lane===0?'#ff96c6':'#b4a0ff';
    ctx.fillStyle=lane===0?'#ff94c60a':'#aa92ff0a';ctx.fillRect(0,y-H*.045,W,H*.09);
    ctx.strokeStyle=col+'65';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W*.035,y+H*.045);ctx.lineTo(W*.965,y+H*.045);ctx.stroke();
    ctx.fillStyle=col;ctx.globalAlpha=.55;ctx.fillRect(W*.18-1,y-H*.047,2,H*.094);ctx.globalAlpha=1;
    const pulse=state==='playing'?.7+.3*Math.sin(t*10):.65;
    const gl=ctx.createRadialGradient(W*.18,y,2,W*.18,y,H*.075);gl.addColorStop(0,col+'66');gl.addColorStop(1,col+'00');ctx.fillStyle=gl;ctx.globalAlpha=pulse;ctx.fillRect(W*.18-H*.08,y-H*.08,H*.16,H*.16);ctx.globalAlpha=1;
  }
  function drawNote(n,t){
    const cfg=settings[difficulty],travel=1.7,x=W*.18+(n.time-t)*W*.48/travel,y=H*(n.lane===0?.635:.765),col=n.lane===0?'#ff9cc9':'#b6a2ff';
    if(x<-40||x>W+40)return;
    const scale=clamp(.65+(x/W)*.42,.65,1.08),sz=Math.min(W,H)*.036*scale;
    ctx.save();ctx.translate(x,y);ctx.rotate(Math.PI/4);ctx.shadowColor=col;ctx.shadowBlur=18;
    roundedRect(-sz/2,-sz/2,sz,sz,sz*.2,col);
    ctx.shadowBlur=0;roundedRect(-sz*.29,-sz*.29,sz*.58,sz*.58,sz*.14,'#fff9');
    ctx.restore();
    ctx.globalAlpha=.22;ctx.strokeStyle=col;ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,sz*.92,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;
  }
  function drawAvatar(t){
    const x=W*.105,y=H*.69, bounce=state==='playing'?Math.sin(t*settings[difficulty].bpm*Math.PI/30)*H*.009:Math.sin(t*2)*H*.008;
    ctx.save();ctx.translate(x,y+bounce);
    // shadow
    ctx.fillStyle='#09081788';ctx.beginPath();ctx.ellipse(0,H*.052,H*.038,H*.012,0,0,Math.PI*2);ctx.fill();
    // jacket/body, energetic original silhouette
    ctx.fillStyle='#f3a5d0';ctx.beginPath();ctx.moveTo(-H*.023,-H*.018);ctx.quadraticCurveTo(-H*.034,H*.018,-H*.012,H*.041);ctx.lineTo(H*.015,H*.035);ctx.lineTo(H*.025,-H*.012);ctx.closePath();ctx.fill();
    ctx.fillStyle='#282043';ctx.beginPath();ctx.moveTo(-H*.012,H*.025);ctx.lineTo(0,H*.023);ctx.lineTo(-H*.006,H*.06);ctx.lineTo(-H*.021,H*.058);ctx.closePath();ctx.fill();
    ctx.fillStyle='#292044';ctx.beginPath();ctx.moveTo(H*.004,H*.024);ctx.lineTo(H*.016,H*.025);ctx.lineTo(H*.027,H*.054);ctx.lineTo(H*.011,H*.058);ctx.closePath();ctx.fill();
    // face
    ctx.fillStyle='#ffd2c9';ctx.beginPath();ctx.ellipse(0,-H*.031,H*.021,H*.023,-.15,0,Math.PI*2);ctx.fill();
    // hair swoop
    ctx.fillStyle='#533a72';ctx.beginPath();ctx.moveTo(-H*.022,-H*.031);ctx.quadraticCurveTo(-H*.019,-H*.065,H*.009,-H*.058);ctx.quadraticCurveTo(H*.03,-H*.051,H*.022,-H*.019);ctx.quadraticCurveTo(H*.008,-H*.039,-H*.003,-H*.027);ctx.lineTo(-H*.022,-H*.031);ctx.fill();
    ctx.fillStyle='#ffeef5';ctx.fillRect(H*.008,-H*.033,H*.004,H*.003);
    // trailing scarf
    ctx.fillStyle='#ff88bd';ctx.beginPath();ctx.moveTo(-H*.015,-H*.006);ctx.quadraticCurveTo(-H*.055,-H*.012,-H*.065,-H*.045+Math.sin(t*5)*H*.008);ctx.quadraticCurveTo(-H*.041,H*.002,-H*.013,H*.014);ctx.fill();
    ctx.restore();
  }
  function render(t){
    drawBackground(t);drawLane(0,t);drawLane(1,t);
    if(state==='playing'||state==='paused'){
      const now=state==='playing'?elapsed:elapsed;
      for(const n of notes)if(!n.done)drawNote(n,now);
    } else if(state==='menu'){
      // A few ambient notes drift past while the title screen waits.
      for(let i=0;i<5;i++){const x=((W*.25+i*W*.23-(t*W*.05)%W)+W)%W;const lane=i%2;drawNote({time:0,lane},t-(x-W*.18)/(W*.48/1.7));}
    }
    drawAvatar(t);
    if(state==='playing'){
      for(const p of particles){ctx.globalAlpha=clamp(p.life/.65,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.28);ctx.fill()}ctx.globalAlpha=1;
    }
  }
  function loop(ms){
    const now=ms/1000,dt=Math.min(.04,lastFrame?now-lastFrame:0);lastFrame=now;
    if(state==='playing'){
      elapsed=now-startAt;
      const cfg=settings[difficulty],beat=60/cfg.bpm,b=Math.floor(elapsed/beat);
      while(lastBeat<b){lastBeat++;beatSound(elapsed,lastBeat)}
      for(const n of notes){if(!n.done&&elapsed>n.time+cfg.window){n.done=true;attempts++;combo=0;health=clamp(health-5,0,100);updateHud();if(health<=0){endGame();break}}}
      ui.progress.style.width=clamp(elapsed/(cfg.beats*beat),0,1)*100+'%';
      particles=particles.filter(p=>p.life>0);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=230*dt;p.life-=dt}
      if(elapsed>=cfg.beats*beat+1)endGame();
    }
    render(now);requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();

